Ltac kr_ag AG KR name :=
  let K2 := fresh in let K4 := fresh in let K18 := fresh in let K19 := fresh in let K20 := fresh in let K21 := fresh in let K22 := fresh in
  let K23 := fresh in let K24 := fresh in let K25 := fresh in let K3 := fresh in
  pose proof KR as (K2 & K4 & K18 & K19 & K20 & K21 & K22 & K23 & K24 & K25 & K3);
  rewrite <- (AG 2%bv) in K2 by notin_list; rewrite <- (AG 4%bv) in K4 by notin_list; rewrite <- (AG 18%bv) in K18 by notin_list;
  rewrite <- (AG 19%bv) in K19 by notin_list; rewrite <- (AG 20%bv) in K20 by notin_list; rewrite <- (AG 21%bv) in K21 by notin_list;
  rewrite <- (AG 22%bv) in K22 by notin_list; rewrite <- (AG 23%bv) in K23 by notin_list; rewrite <- (AG 24%bv) in K24 by notin_list;
  rewrite <- (AG 25%bv) in K25 by notin_list; rewrite <- (AG 3%bv) in K3 by notin_list;
  pose proof (conj K2 (conj K4 (conj K18 (conj K19 (conj K20 (conj K21 (conj K22 (conj K23 (conj K24 (conj K25 K3)))))))))) as name;
  clear K2 K4 K18 K19 K20 K21 K22 K23 K24 K25 K3.

