  getr R 2 = Z_to_bv 64 (s - 272) /\ getr R 4 = Z_to_bv 64 301120 /\ getr R 18 = Z_to_bv 64 (2 ^ 64 - 10) /\ getr R 19 = Z_to_bv 64 W /\
