  LIVK A m m' -> sub_live A A' -> live A (Z_to_bv 64 parr) = Some 80%Z -> (0 <= i < 10)%Z -> (0 <= parr)%Z -> (parr + 80 <= 2 ^ 64)%Z ->
  bc_mem C A7 A' m' parr w h i pix data.
