Definition bc_fl3 (regs fr : bvmap 5 word) (minv maxv bil pa bsc nc datas wpls : Z) : list cell :=
  bc_fl1 regs fr minv maxv ++ [(0%Z, 8%nat, bil); (48%Z, 8%nat, pa); (40%Z, 8%nat, bsc); (32%Z, 8%nat, nc);
                               (24%Z, 8%nat, (datas + 11 * (4 * wpls) + 22)%Z); (16%Z, 8%nat, (datas + 11 * (4 * wpls) + 1)%Z); (8%Z, 8%nat, (2 ^ 64 - 40)%Z)].

