  hdr_ok (w + 22) (h + 22) 8 -> hdr_ok w h 8 -> (1 <= w)%Z -> (1 <= h)%Z ->
  PIXat m7 bsc (hdv (w + 22) (h + 22) 8 0 datas) -> live A7 (Z_to_bv 64 bsc) = Some 64%Z -> live A7 (Z_to_bv 64 datas) = Some (4 * (wpl_of (w + 22) 8 * (h + 22)))%Z ->
  (0 <= nc < 2 ^ 64)%Z -> live A7 (Z_to_bv 64 nc) = Some 40%Z ->
  (forall j, (0 <= j < 10)%Z -> rdn SEGS m7 (Z_to_bv 64 (nc + 4 * j)) 4 = Some (Z_to_le_bytes 4 (nc_val minv maxv j))) -> (0 <= minv <= 255)%Z -> (0 <= maxv <= 255)%Z ->
  (0 <= spat < 2 ^ 64)%Z -> live A7 (Z_to_bv 64 spat) = Some 44%Z -> (0 <= rng < 2 ^ 64)%Z -> live A7 (Z_to_bv 64 rng) = Some 1024%Z ->
  (0 <= idx < 10)%Z ->
  bc_inv C A7 A m7 m s pa parr ba barr w h idx pixes datad (bc_fl3 regs0 fr0 minv maxv bil pa bsc nc datas (wpl_of (w + 22) 8)) ->
  bc_kr regs s (4 * wpl_of (w + 22) 8) h w spat rng g3 -> getr regs 8 = Z_to_bv 64 idx -> getr regs 11 = Z_to_bv 64 bsc -> getr regs 26 = Z_to_bv 64 nc ->
  forall (kR bR : Z), aroom A vm kR bR -> (RK_it <= kR)%Z -> (RB_it w h <= bR)%Z ->
  (forall fr' cs' A' m' vm' regs' (pixes' datad' : Z -> Z), W C A' m' (with_vmmaps vm' md) -> frm_zero cs' ->
     bc_inv C A7 A' m7 m' s pa parr ba barr w h (idx + 1) pixes' datad' (bc_fl3 regs0 fr0 minv maxv bil pa bsc nc datas (wpl_of (w + 22) 8)) ->
     bc_kr regs' s (4 * wpl_of (w + 22) 8) h w spat rng g3 -> getr regs' 8 = Z_to_bv 64 (idx + 1) -> getr regs' 11 = Z_to_bv 64 bsc -> getr regs' 26 = Z_to_bv 64 nc ->
     hc_fp fr fr' -> aroom A' vm' (kR - RK_it) (bR - RB_it w h) ->
     realizes SEGS (mkCfg (@mkst (mkFP fr' cs') regs' (Z_to_bv 64 (if (idx =? 9)%Z then 188220 else 187564)) m' al_rom) (with_vmmaps vm' md)) S) ->
  realizes SEGS (mkCfg (@mkst (mkFP fr cs) regs (Z_to_bv 64 187564) m al_rom) (with_vmmaps vm md)) S.
Proof.
