(* [comment removed for export] *)
Lemma bc_loop_W : forall (n : nat) fr cs C A7 A m7 m md vm regs regs0 fr0 (s bsc datas nc spat rng pa parr ba barr w h minv maxv bil idx : Z) (pixes datad : Z -> Z) (S : TSet) (g3 : word),
  (Z.of_nat n + 1 = 10 - idx)%Z -> (0 <= idx)%Z ->
  Cok C -> W C A m (with_vmmaps vm md) -> frm_zero cs -> (s mod 16 = 0)%Z -> (c_top C - LSTK + BC_WIN <= s)%Z -> (s <= c_top C)%Z ->
  bc_cst A7 m7 bsc datas nc spat rng w h minv maxv ->
  bc_inv C A7 A m7 m s pa parr ba barr w h idx pixes datad (bc_fl3 regs0 fr0 minv maxv bil pa bsc nc datas (wpl_of (w + 22) 8)) ->
  bc_kr regs s (4 * wpl_of (w + 22) 8) h w spat rng g3 -> getr regs 8 = Z_to_bv 64 idx -> getr regs 11 = Z_to_bv 64 bsc -> getr regs 26 = Z_to_bv 64 nc ->
  forall (kR bR : Z), aroom A vm kR bR -> ((10 - idx) * RK_it <= kR)%Z -> ((10 - idx) * RB_it w h <= bR)%Z ->
  (forall fr' cs' A' m' vm' regs' (pixes' datad' : Z -> Z), W C A' m' (with_vmmaps vm' md) -> frm_zero cs' ->
     bc_inv C A7 A' m7 m' s pa parr ba barr w h 10 pixes' datad' (bc_fl3 regs0 fr0 minv maxv bil pa bsc nc datas (wpl_of (w + 22) 8)) ->
     bc_kr regs' s (4 * wpl_of (w + 22) 8) h w spat rng g3 -> hc_fp fr fr' -> aroom A' vm' (kR - (10 - idx) * RK_it) (bR - (10 - idx) * RB_it w h) ->
     realizes SEGS (mkCfg (@mkst (mkFP fr' cs') regs' (Z_to_bv 64 188220) m' al_rom) (with_vmmaps vm' md)) S) ->
