Lemma bc_comp_W : forall fr cs C A7 m7 md vm7 regs regs0 fr0 (s pixs bsc datas nc spat rng w h minv maxv bil : Z) (v : pixv) (S : TSet) (g3 : word),
  Cok C -> W C A7 m7 (with_vmmaps vm7 md) -> frm_zero cs -> (s mod 16 = 0)%Z -> (c_top C - LSTK + BC_WIN <= s)%Z -> (s <= c_top C)%Z ->
  bc_cst A7 m7 bsc datas nc spat rng w h minv maxv ->
  PIXat m7 pixs v -> p_w v = w -> p_h v = h -> live A7 (Z_to_bv 64 pixs) = Some 64%Z ->
  cellsAt SEGS m7 (s - 272) (bc_fl1 regs0 fr0 minv maxv ++ [(0%Z, 8%nat, bil)]) ->
  getr regs 1 = Z_to_bv 64 187320 -> getr regs 2 = Z_to_bv 64 (s - 272) -> getr regs 4 = Z_to_bv 64 301120 -> getr regs 10 = Z_to_bv 64 10 ->
  getr regs 19 = Z_to_bv 64 bsc -> getr regs 21 = Z_to_bv 64 1 -> getr regs 22 = Z_to_bv 64 pixs -> getr regs 23 = Z_to_bv 64 spat -> getr regs 24 = Z_to_bv 64 rng ->
  getr regs 26 = Z_to_bv 64 nc -> getr regs 3 = g3 -> reg_get fr 9 = Z_to_bv 64 4621819117588971520 ->
  forall (kR bR : Z), aroom A7 vm7 kR bR -> (4 + 10 * RK_it <= kR)%Z -> (4 * 2 ^ 17 + 10 * RB_it w h <= bR)%Z ->
  (forall fr' cs' A' m' vm' regs' (pa parr ba barr : Z) (pixes datad : Z -> Z), W C A' m' (with_vmmaps vm' md) -> frm_zero cs' ->
     bc_inv C A7 A' m7 m' s pa parr ba barr w h 10 pixes datad (bc_fl3 regs0 fr0 minv maxv bil pa bsc nc datas (wpl_of (w + 22) 8)) ->
     bc_kr regs' s (4 * wpl_of (w + 22) 8) h w spat rng g3 ->
     (forall r : reg, r <> 8%bv -> r <> 12%bv -> r <> 13%bv -> r <> 14%bv -> r <> 15%bv -> reg_get fr' r = reg_get fr r) ->
     aroom A' vm' (kR - 4 - 10 * RK_it) (bR - 4 * 2 ^ 17 - 10 * RB_it w h) ->
     realizes SEGS (mkCfg (@mkst (mkFP fr' cs') regs' (Z_to_bv 64 188220) m' al_rom) (with_vmmaps vm' md)) S) ->
  realizes SEGS (mkCfg (@mkst (mkFP fr cs) regs (Z_to_bv 64 98280) m7 al_rom) (with_vmmaps vm7 md)) S.
